#![allow(unused_imports)]
use verus::prelude::*;

#[requires(true)]
// xgrid and ygrid each have as many rows as y has elements:
#[ensures(ret.0.len() == y.len())]
#[ensures(ret.1.len() == y.len())]
// Every row of xgrid is exactly a clone of the original x:
#[ensures(
    forall(|i: usize| i < y.len() ==>
        ret.0[i] == x
    )
)]
// Every row of ygrid has length x.len(), and all its entries equal the corresponding y[i]:
#[ensures(
    forall(|i: usize| i < y.len() ==>
        ret.1[i].len() == x.len()
        && forall(|j: usize| j < x.len() ==>
            ret.1[i][j] == y[i]
        )
    )
)]
fn meshgrid(x: Vec<f32>, y: Vec<f32>) -> (Vec<Vec<f32>>, Vec<Vec<f32>>) {
    let nx = x.len();
    let mut xgrid = Vec::with_capacity(y.len());
    let mut ygrid = Vec::with_capacity(y.len());

    for &yi in &y {
        // Each row of xgrid is a copy of x
        xgrid.push(x.clone());
        // Each row of ygrid is yi repeated nx times
        ygrid.push(vec![yi; nx]);
    }

    (xgrid, ygrid)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_meshgrid() {
        let x = vec![1.0, 2.0, 3.0];
        let y = vec![4.0, 5.0];
        let (xg, yg) = meshgrid(x, y);

        // xg should be 2 rows, each [1.0, 2.0, 3.0]
        assert_eq!(xg.len(), 2);
        assert_eq!(xg[0], vec![1.0, 2.0, 3.0]);
        assert_eq!(xg[1], vec![1.0, 2.0, 3.0]);

        // yg should be [[4.0, 4.0, 4.0], [5.0, 5.0, 5.0]]
        assert_eq!(yg.len(), 2);
        assert_eq!(yg[0], vec![4.0, 4.0, 4.0]);
        assert_eq!(yg[1], vec![5.0, 5.0, 5.0]);
    }
}